import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Actuacion } from '../../actuaciones/entities/actuacion.entity';
import { Artista } from '../../artistas/entities/artista.entity';

@Injectable()
export class AsignarArtistaRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Actuacion) private readonly actuaciones: Repository<Actuacion>,
    @InjectRepository(Artista) private readonly artistas: Repository<Artista>
  ) {}

  buscarActuacionRepository(actuacionId: number) {
    return this.actuaciones.findOneBy({ id: actuacionId });
  }

  buscarArtistaRepository(artistaId: number) {
    return this.artistas.findOneBy({ id: artistaId });
  }

  async asignarArtistaRepository(actuacionId: number, artistaId: number, rol: string) {
    const asignacion = { actuacionId, artistaId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarArtistaRepository } from './repository';

@Injectable()
export class AsignarArtistaService {
  constructor(private readonly repository: AsignarArtistaRepository) {}

  async asignarArtistaService(actuacionId: number, artistaId: number, rol: string) {
    const actuacion = await this.repository.buscarActuacionRepository(actuacionId);
    const artista = await this.repository.buscarArtistaRepository(artistaId);
    if (!actuacion || !artista) {
      throw new NotFoundException('No existe la actuacion o el artista');
    }

    try {
      return await this.repository.asignarArtistaRepository(actuacionId, artistaId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El artista ya está asignado a esa actuacion');
      }
      throw error;
    }
  }
}

